// Entry privacy and local search. Journal contents never leave this page through these tools.
export function setupArchiveTools(bridge) {
  const {editor}=bridge,button=document.createElement('button');button.id='writerArchiveBtn';button.type='button';button.className='quiet';button.textContent='Entries, privacy and search';document.querySelector('.tool-row').append(button);
  const dialog=document.createElement('dialog');dialog.id='archiveTools';dialog.className='browser-dialog';dialog.setAttribute('aria-labelledby','archiveToolsHeading');
  dialog.innerHTML=`<h2 id="archiveToolsHeading">Entries, privacy and search</h2><button id="archiveClose" type="button">Close</button><p>Public entries remain readable inside the archive and are included in its search index. Protected entries require an unlock method. Dates and encryption metadata remain visible. If any protection is enabled, all attachments and journal settings are encrypted.</p><button id="archiveSetup" type="button">Set up a passphrase</button><section id="archivePrivacySection" aria-labelledby="archivePrivacyHeading"><h3 id="archivePrivacyHeading">Entry privacy</h3><p>Check an entry to protect it. New entries start protected once you have set up a passphrase. Making an entry public exposes its text, tags and recorded measurements in the portable search index. Copies saved earlier keep their earlier privacy settings.</p><div id="archiveEntryList"></div><button id="archiveApply" type="button">Save privacy choices</button></section><section aria-labelledby="archiveSearchHeading"><h3 id="archiveSearchHeading">Search this journal</h3><form id="archiveSearchForm" autocomplete="off"><label>Words<input id="archiveQuery" maxlength="300" type="search"></label><label>Tag<input id="archiveTag" maxlength="100" placeholder="walk"></label><label>From day<input id="archiveFrom" type="date"></label><label>Through day<input id="archiveTo" type="date"></label><label>Measurement name<input id="archiveMetric" maxlength="100" placeholder="mood"></label><label>Minimum value<input id="archiveMin" type="number" step="any"></label><label>Maximum value<input id="archiveMax" type="number" step="any"></label><button id="archiveSearch" type="submit">Search locally</button></form><div id="archiveResults"></div></section><p id="archiveStatus" role="status" aria-live="polite"></p>`;
  document.body.append(dialog);const $=id=>dialog.querySelector('#'+id);let identity,revision,source='',generation=0;
  const say=text=>{$('archiveStatus').textContent=text;};
  function reset(){generation++;dialog.close();$('archiveEntryList').replaceChildren();$('archiveResults').replaceChildren();$('archiveSearchForm').reset();say('');}
  const open=()=>{if(bridge.isLocked()&&!bridge.publicAvailable())return;identity=bridge.identity();revision=bridge.revision();source=editor.value;$('archiveEntryList').replaceChildren();$('archiveResults').replaceChildren();const protectedJournal=bridge.hasSession();$('archivePrivacySection').hidden=bridge.isLocked();$('archiveSetup').textContent=bridge.isLocked()?'Unlock protected entries':'Set up a passphrase';$('archiveSetup').hidden=protectedJournal;$('archiveApply').disabled=!protectedJournal;for(const [index,entry] of bridge.entries().entries()){const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=entry.private;check.disabled=!protectedJournal;check.dataset.id=entry.id;label.append(check,document.createTextNode(' Protect '+(entry.date||'Undated writing')+' · entry '+(index+1)));$('archiveEntryList').append(label);}say('Privacy choices apply after Save privacy choices. Search stays on this device.');dialog.showModal();};
  button.onclick=open;
  $('archiveSetup').onclick=()=>{const locked=bridge.isLocked();reset();document.getElementById(locked?'lockGateUnlock':'lockBtn').click();};
  $('archiveApply').onclick=async()=>{if(identity!==bridge.identity()||revision!==bridge.revision()||source!==editor.value){say('The journal changed. Close and reopen this tool before changing privacy.');return;}const ticket=generation;$('archiveApply').disabled=true;try{const ids=[...$('archiveEntryList').querySelectorAll('input:checked')].map(input=>input.dataset.id);const ok=await bridge.setPrivacy(ids);if(ticket!==generation)return;revision=bridge.revision();if(!ok)throw Error('Privacy choices could not be saved. The previous browser copy may still be public. Download the journal or retry.');revision=bridge.revision();say('Saved privacy choices in this browser. Download or Save the journal to update a separate device file.');}catch(error){if(ticket===generation)say(error.message);}finally{if(ticket===generation)$('archiveApply').disabled=false;}};
  $('archiveSearchForm').onsubmit=async event=>{event.preventDefault();if(identity!==bridge.identity()){reset();return;}const ticket=++generation;$('archiveSearch').disabled=true;$('archiveResults').replaceChildren();say('Searching local entries…');try{const optional=id=>$(id).value===''?null:Number($(id).value),entries=await bridge.search({query:$('archiveQuery').value,tag:$('archiveTag').value,from:$('archiveFrom').value,to:$('archiveTo').value,metric:$('archiveMetric').value,min:optional('archiveMin'),max:optional('archiveMax')});if(ticket!==generation||!dialog.open)return;for(const entry of entries){const row=document.createElement('article'),heading=document.createElement('h4'),text=document.createElement('p');heading.textContent=(entry.date||'Undated writing')+' · '+(entry.private?'Protected':'Public');text.textContent=entry.source.replace(/\s+/g,' ').slice(0,240);row.append(heading,text);$('archiveResults').append(row);}say(entries.length+' matching entries. Protected text is searched in memory while unlocked.');}catch(error){if(ticket===generation)say(error.message);}finally{$('archiveSearch').disabled=false;}};
  $('archiveClose').onclick=()=>{reset();editor.focus();};dialog.addEventListener('cancel',reset);globalThis.addEventListener('pagehide',reset);
  return {reset,open};
}
